module shortest_time (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [15:0] v_walk,\n    input wire [15:0] v_bike,\n    input wire [15:0] x1,\n    input wire [15:0] y1,\n    input wire [15:0] x2,\n    input wire [15:0] y2,\n    input wire [15:0] xG,\n    input wire [15:0] yG,\n    input wire [15:0] xD,\n    input wire [15:0] yD,\n    input wire [1:0] n,\n    input wire [15:0] station_x_0,\n    input wire [15:0] station_y_0,\n    input wire [15:0] station_x_1,\n    input wire [15:0] station_y_1,\n    input wire [15:0] station_x_2,\n    input wire [15:0] station_y_2,\n    input wire [15:0] station_x_3,\n    input wire [15:0] station_y_3,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // States declaration\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] CALC_DIST    = 3'd1;\n    localparam [2:0] ADD_BIKE     = 3'd2;\n    localparam [2:0] DIJKSTRA     = 3'd3;\n    localparam [2:0] FINISH       = 3'd4;\n\n    reg [2:0] state, next_state;\n    reg [7:0] cycle_count;\n    reg [7:0] i, j, k;  // Counters\n    localparam MAX_NODES = 4'd10;\n    localparam MAX_EDGES = 8'd100;\n\n    // Node coordinates storage\n    reg [15:0] nodes_x [0:9];\n    reg [15:0] nodes_y [0:9];\n\n    // Graph representation\n    reg [31:0] adj_matrix [0:99];  // MAX_NODES*MAX_NODES = 100 entries (Q16.16)\n    reg [31:0] dist [0:9];        // Shortest distances\n    reg visited [0:9];            // Visited nodes\n\n    // Internal calculation registers\n    reg [31:0] min_time;\n    reg [3:0] current_node;\n    reg [15:0] dx, dy;\n    reg [31:0] temp_dist;\n\n    // Distance calculation sqrt(dx² + dy²)\n    wire [31:0] distance;\n    distance_calc dist_calc (\n        .clk(clk),\n        .dx(dx),\n        .dy(dy),\n        .result(distance)\n    );\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            cycle_count <= 8'd0;\n\n            for (i = 0; i < 10; i = i + 1) begin\n                nodes_x[i] <= 16'd0;\n                nodes_y[i] <= 16'd0;\n                dist[i] <= 32'h7FFF_FFFF;  // Max Q16.16 value\n                visited[i] <= 1'b0;\n            end\n\n            for (i = 0; i < 100; i = i + 1) begin\n                adj_matrix[i] <= 32'h7FFF_FFFF;\n            end\n\n        end else begin\n            cycle_count <= cycle_count + 8'd1;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Load nodes (start, end, stations, corners)\n                        nodes_x[0] <= x1; nodes_y[0] <= y1;\n                        nodes_x[1] <= x2; nodes_y[1] <= y2;\n                        nodes_x[2] <= station_x_0; nodes_y[2] <= station_y_0;\n                        nodes_x[3] <= station_x_1; nodes_y[3] <= station_y_1;\n                        nodes_x[4] <= station_x_2; nodes_y[4] <= station_y_2;\n                        nodes_x[5] <= station_x_3; nodes_y[5] <= station_y_3;\n                        nodes_x[6] <= xG; nodes_y[6] <= yG;\n                        nodes_x[7] <= xD; nodes_y[7] <= yD;\n                        state <= CALC_DIST;\n                        i <= 8'd0;\n                        j <= 8'd0;\n                    end\n                end\n\n                CALC_DIST: begin\n                    dx <= nodes_x[i] - nodes_x[j];\n                    dy <= nodes_y[i] - nodes_y[j];\n                    // Assume square root calculation takes 1 cycle (pipelined)\n                    // Walking speed division: distance / v_walk\n                    adj_matrix[i*10 + j] = {16'd0, distance[31:16]} / v_walk;  // Q16.16 result\n\n                    if (j == MAX_NODES-1) begin\n                        j <= 8'd0;\n                        if (i == MAX_NODES-1) begin\n                            state <= ADD_BIKE;\n                            i <= 8'd2;  // Start from first station\n                        end else begin\n                            i <= i + 8'd1;\n                        end\n                    end else begin\n                        j <= j + 8'd1;\n                    end\n                end\n\n                ADD_BIKE: begin\n                    if (i < 2 + n) begin // Stations 0..(n-1)\n                        dx <= nodes_x[i] - nodes_x[j];\n                        dy <= nodes_y[i] - nodes_y[j];\n                        // Bike speed division: distance / v_bike\n                        temp_dist <= {16'd0, distance[31:16]} / v_bike;\n                        if (temp_dist < adj_matrix[i*10 + j]) begin\n                            adj_matrix[i*10 + j] <= temp_dist;\n                            adj_matrix[j*10 + i] <= temp_dist;\n                        end\n\n                        if (j == MAX_NODES-1) begin\n                            j <= 8'd0;\n                            if (i == 2 + n -1) begin\n                                state <= DIJKSTRA;\n                                i <= 8'd0;\n                                // Initialize Dijkstra\n                                dist[0] <= 32'd0;  // Start node\n                                current_node <= 4'd0;\n                                k <= 8'd0;\n                            end else begin\n                                i <= i + 8'd1;\n                            end\n                        end else begin\n                            j <= j + 8'd1;\n                        end\n                    end\n                end\n\n                DIJKSTRA: begin\n                    if (!visited[current_node]) begin\n                        visited[current_node] <= 1'b1;\n                        // Update neighbors\n                        for (j = 0; j < MAX_NODES; j = j + 1) begin\n                            if (!visited[j]) begin\n                                if (dist[current_node] + adj_matrix[current_node*10 + j] < dist[j]) begin\n                                    dist[j] <= dist[current_node] + adj_matrix[current_node*10 + j];\n                                end\n                            end\n                        end\n                    end\n\n                    // Find next node: min unvisited\n                    min_time <= 32'h7FFF_FFFF;\n                    current_node <= 4'd0;\n                    for (i = 0; i < MAX_NODES; i = i + 1) begin\n                        if (!visited[i] && dist[i] < min_time) begin\n                            min_time <= dist[i];\n                            current_node <= i[3:0];\n                        end\n                    end\n\n                    // Check if destination visited\n                    if (visited[1] || k == MAX_NODES-1) begin\n                        result <= dist[1];\n                        state <= FINISH;\n                    end\n                    k <= k + 8'd1;\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    if (cycle_count > 8'd10) begin  // Hold done for 10 cycles\n                        state <= IDLE;\n                    end\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule\n\n// Euclidean distance calculator (Q16.16 output)\nmodule distance_calc (\n    input wire clk,\n    input wire [15:0] dx,\n    input wire [15:0] dy,\n    output reg [31:0] result\n);\n    reg [31:0] dx_sq, dy_sq;\n    reg [31:0] sum;\n    // Non-restoring square root implementation here (simplified)\n    always @(posedge clk) begin\n        dx_sq <= (dx * dx);\n        dy_sq <= (dy * dy);\n        sum <= dx_sq + dy_sq;\n        result <= sqrt(sum);  // Actual sqrt implementation needed\n    end\nendmodule